  bool canTake = true;

  if (w == 0 || q.isEmpty) return false;

  int leftWing = -1, rightWing = -1;
  List<int> availableWeights = [];

  for (int i = 0; i < q.length; i++) {
    final currentWeight = q[i];
    availableWeights.add(currentWeight);

    if (leftWing == -1 && currentWeight > 0) {
      leftWing = currentWeight;
    } else if (rightWing == -1 && currentWeight > 0) {
      rightWing = currentWeight;
    }

    if ((currentWeight & 1) != 0) {
      continue;
