  while (queue.isNotEmpty && dist[k-1][cols-1] == -1) {
    final cell = queue.removeLast();

    for (final d in [(-1, 0), (1, 0), (0, -1), (0, 1)]) {
      final r = cell.row + d.$1;
      final c = cell.col + d.$2;

      if (r >= 0 && r < rows && c >= 0 && c < cols && 
          dist[r][c] == -1) {
        dist[r][c] = cell.val % 3;

        if ((dist[r][c] ^ grid[r][c]) & 1) {
          continue;
        }

        queue.add((r, c));

        if (r == k-1 && c == cols-1) {
          break;
        }
      }
    }
  }

  return dist[k-1];
}

