  var lo = a;
  var hi = b;

  if (lo > hi) {
    final tmp = lo;
    lo = hi;
    hi = tmp;
  }

  final result = <int>[];

  for (var i = lo; i <= hi; i++) {
    if (i % 2 == 0) {
      result.add(i);
    }
  }

  return result;
}

